package vn.aicrm.shared;

import java.util.*;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.http.*;
import org.springframework.web.multipart.MultipartFile;
import static vn.aicrm.shared.RetailAccess.*;

@RestController
@RequestMapping("/api/v1/retail")
public class RetailController {
  @org.springframework.beans.factory.annotation.Autowired private RetailLocations locations;
  @GetMapping("/locations/{kind}") Object locations(Authentication a,@PathVariable String kind){if(!Set.of("branches","warehouses").contains(kind))throw problem("INVALID_CATALOG","Danh mục không hợp lệ");return locations.list(a,kind);}
  @PostMapping("/locations/{kind}") Object addLocation(Authentication a,@PathVariable String kind,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"LOCATION_CREATE_"+kind,x,()->locations.save(a,kind,null,x));}
  @PostMapping("/locations/{kind}/{id}") Object saveLocation(Authentication a,@PathVariable String kind,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"LOCATION_UPDATE_"+kind,x,()->locations.save(a,kind,id,x));}
  @GetMapping("/onboarding") Object onboarding(Authentication a){return locations.onboarding(a);}
  @GetMapping("/location-owners") Object locationOwners(Authentication a){if(!r.granular(a,"locations","VIEW")&&!r.granular(a,"warehouses","VIEW")&&!r.granular(a,"setup","VIEW"))throw problem("PERMISSION_DENIED","Không có quyền quản lý địa điểm/kho",HttpStatus.FORBIDDEN);return r.db.queryForList("select id,display_name,email from identity.account where tenant_id=? and enabled order by display_name",r.tenant(a));}
  @GetMapping("/locations/{kind}/export") Object exportLocations(Authentication a,@PathVariable String kind){if(!Set.of("branches","warehouses").contains(kind))throw problem("INVALID_CATALOG","Danh mục không hợp lệ");r.gate(a,kind.equals("branches")?"locations":"warehouses","EXPORT");return commands.export(a,kind,()->locations.list(a,kind));}
  @PostMapping("/onboarding") Object progress(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"ONBOARDING",x,()->locations.progress(a,x));}
  private final RetailAccess r;private final RetailPartners partners;private final RetailCommands commands;private final RetailCatalog catalog;private final RetailDocuments documents;private final InventoryPort inventory;private final RetailFinance finance;private final RetailOperations operations;private final RetailImport imports;private final RetailCommissions commissions;private final RetailWarehouseConfigService retailWarehouseConfigService;
  public RetailController(RetailAccess r,RetailCommands commands,RetailCatalog catalog,RetailDocuments documents,InventoryPort inventory,RetailFinance finance,RetailOperations operations,RetailImport imports,RetailCommissions commissions,RetailPartners partners,RetailWarehouseConfigService retailWarehouseConfigService){this.retailWarehouseConfigService=retailWarehouseConfigService;this.r=r;this.partners=partners;this.commands=commands;this.catalog=catalog;this.documents=documents;this.inventory=inventory;this.finance=finance;this.operations=operations;this.imports=imports;this.commissions=commissions;}
  @GetMapping("/uom-conversions") Object uomConversions(Authentication a){r.gate(a,"uom-conversions","VIEW");return Map.of("units",r.db.queryForList("select * from retail.uom where tenant_id=? order by name",r.tenant(a)),"conversions",r.db.queryForList("select c.*,s.code,s.name as product,u.name as unit,s.unit as base_unit from retail.uom_conversion c join retail.sku s on s.tenant_id=c.tenant_id and s.id=c.product_id join retail.uom u on u.tenant_id=c.tenant_id and u.id=c.uom_id where c.tenant_id=? order by s.code,u.name",r.tenant(a)));}
  @PostMapping("/uom-conversions") Object saveUomConversion(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"UOM_CONVERSION",x,()->{r.require(a,"SETUP");var t=r.tenant(a);var product=uuid(x,"productId");var sku=r.one("sku",t,product);var unit=r.db.queryForList("select * from retail.uom where tenant_id=? and id=?",t,uuid(x,"uomId"));if(unit.isEmpty())throw problem("INVALID_UOM","Đơn vị không tồn tại");var name=unit.getFirst().get("name").toString();var factor=positive(x,"factor");if(factor.scale()>4)throw problem("INVALID_UOM","Tỷ lệ tối đa 4 chữ số thập phân");if(name.equals(sku.get("unit")))throw problem("BASE_UOM","Đơn vị cơ sở luôn có tỷ lệ 1");r.db.queryForObject("select id from retail.sku where tenant_id=? and id=? for update",UUID.class,t,product);r.db.update("update retail.sku set units=jsonb_set(units,array[?]::text[],to_jsonb(?::numeric),true) where tenant_id=? and id=?",name,factor,t,product);return Map.of("ok",true);});}
  @GetMapping("/warehouse-config") Object warehouseConfig(Authentication a){r.require(a,"READ");return r.db.queryForList("select * from retail.warehouse_config where tenant_id=? order by kind,code",r.tenant(a)).stream().filter(c->r.granular(a,new RetailPermissions(r).configFeature(c.get("kind").toString()),"VIEW")).toList();}
  @PostMapping("/warehouse-config") Object saveWarehouseConfig(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"WAREHOUSE_CONFIG",x,()->retailWarehouseConfigService.doSetupConfig(a,x));}
  @GetMapping("/partner-owners") Object partnerOwners(Authentication a){return partners.accounts(a);}
  @GetMapping("/partners") Object partners(Authentication a,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String role,@RequestParam(defaultValue="") String state,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="") String group){return partners.list(a,q,role,state,page,group);}
  @GetMapping("/partners/{id}") Object partner(Authentication a,@PathVariable UUID id){return partners.detail(a,id);}
  @PostMapping("/partners") Object createPartner(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"PARTNER_CREATE",x,()->partners.save(a,null,x));}
  @PostMapping("/customers/quick-create") Object quickCustomer(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CUSTOMER_QUICK_CREATE",x,()->partners.quickCustomer(a,x));}
  @PostMapping("/partners/{id}") Object updatePartner(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"PARTNER_UPDATE_"+id,x,()->partners.save(a,id,x));}
  @GetMapping("/catalog") Object catalog(Authentication a){return catalog.catalog(a);}
  @PostMapping("/catalog/{kind}") Object createCatalog(Authentication a,@PathVariable String kind,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CATALOG_"+kind,x,()->catalog.create(a,kind,x));}
  @PostMapping("/catalog/{kind}/{id}/deactivate") Object deactivate(Authentication a,@PathVariable String kind,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DEACTIVATE_"+kind+"_"+id,x,()->catalog.deactivate(a,kind,id));}
  @GetMapping("/documents") Object documents(Authentication a,@RequestParam(defaultValue="") String type,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page){if(!type.isBlank())r.modules.require(BusinessModules.owner(RetailPermissions.feature(type)));return documents.list(a,type,status,q,page);}
  @GetMapping("/documents/{id}/print") Object print(Authentication a,@PathVariable UUID id){var d=documents.document(a,id);r.gate(a,RetailPermissions.feature(d.get("type").toString()),"PRINT");return documents.detail(a,id);}
  @GetMapping("/documents/{id}") Object detail(Authentication a,@PathVariable UUID id){return documents.detail(a,id);}
  @PostMapping("/documents") Object create(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DOCUMENT_CREATE",x,()->documents.create(a,x));}
  @PostMapping("/documents/{id}/{action}") Object transition(Authentication a,@PathVariable UUID id,@PathVariable String action,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"DOCUMENT_"+action+"_"+id,x,()->documents.transition(a,id,action,x));}
  @GetMapping("/commissions") Object commissions(Authentication a){return commissions.list(a);}
  @PostMapping("/commissions") Object commission(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"COMMISSION_CREATE",x,()->commissions.create(a,x));}
  @GetMapping("/finance") Object finance(Authentication a){return finance.overview(a);}
  @PostMapping("/payments") Object payment(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"PAYMENT_CREATE",x,()->finance.createPayment(a,x));}
  @PostMapping("/allocations") Object allocation(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){r.require(a,"FINANCE");return commands.execute(a,key,"ALLOCATION",x,()->finance.allocate(a,uuid(x,"paymentId"),uuid(x,"openItemId"),num(x,"amount",java.math.BigDecimal.ZERO)));}
  @GetMapping("/customers/{id}/history") Object history(Authentication a,@PathVariable UUID id){return operations.care(a,id);}
  @PostMapping("/care") Object care(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CARE_CREATE",x,()->operations.createCare(a,x));}
  @PostMapping("/care/{id}/complete") Object completeCare(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"CARE_COMPLETE_"+id,x,()->operations.completeCare(a,id));}
  @GetMapping("/summary") Object summary(Authentication a){return operations.summary(a);}
  @GetMapping("/reports") Object report(Authentication a,@RequestParam String from,@RequestParam String to){return operations.report(a,from,to);}
  @PostMapping("/imports") Object preview(Authentication a,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"IMPORT_PREVIEW",x,()->imports.preview(a,x));}
  @PostMapping("/imports/file") Object file(Authentication a,@RequestParam String kind,@RequestParam UUID warehouseId,@RequestParam MultipartFile file,@RequestHeader("Idempotency-Key") String key)throws java.io.IOException{r.require(a,"SETUP");var x=r.json.createObjectNode().put("kind",kind).put("warehouseId",warehouseId.toString());x.set("rows",imports.parse(file.getBytes(),file.getOriginalFilename()==null?"":file.getOriginalFilename()));return commands.execute(a,key,"IMPORT_PREVIEW",x,()->imports.preview(a,x));}
  @PostMapping("/imports/{id}/commit") Object commit(Authentication a,@PathVariable UUID id,@RequestBody JsonNode x,@RequestHeader("Idempotency-Key") String key){return commands.execute(a,key,"IMPORT_COMMIT_"+id,x,()->imports.commit(a,id));}
  @GetMapping("/imports") Object batches(Authentication a){r.require(a,"SETUP");return r.db.queryForList("select * from retail.import_batch b where tenant_id=? and "+r.scope(a,"b")+" order by created_at desc limit 100",r.tenant(a)).stream().filter(b->{try{new RetailPermissions(r).importPermission(a,b.get("kind").toString(),r.node(b.get("rows")));return true;}catch(vn.coreplatform.shared.ApiExceptionHandler.ApiProblem denied){return false;}}).map(r::clean).toList();}
  @GetMapping("/scopes") Object scopes(Authentication a){r.gate(a,"scope","VIEW");return r.db.queryForList("select s.*,a.email,w.name warehouse from retail.access_scope s join identity.account a on a.id=s.account_id join retail.warehouse w on w.tenant_id=s.tenant_id and w.id=s.warehouse_id where s.tenant_id=? and "+r.scope(a,"s"),r.tenant(a));}
  @GetMapping("/export") ResponseEntity<String> export(Authentication a,@RequestParam String kind,@RequestParam(defaultValue="") String from,@RequestParam(defaultValue="") String to){r.require(a,"EXPORT");exportPermission(a,kind);List<Map<String,Object>> rows=(List<Map<String,Object>>)commands.export(a,kind,()->switch(kind){case "suppliers"->r.db.queryForList("select code,name,phone,email,address,active from retail.partner where tenant_id=? and roles->>'SUPPLIER'='true' order by code",r.tenant(a));case "products"->(List<Map<String,Object>>)((Map<?,?>)catalog.catalog(a)).get("skus");case "stock"->(List<Map<String,Object>>)inventory.stock(a);case "movements"->(List<Map<String,Object>>)inventory.movements(a);case "documents"->allDocuments(a);case "payments"->((List<Map<String,Object>>)((Map<?,?>)finance.overview(a)).get("payments")).stream().filter(row->r.granular(a,Set.of("RECEIPT","SUPPLIER_REFUND").contains(row.get("kind"))?"receipt":"payment","EXPORT")).toList();case "finance"->((List<Map<String,Object>>)((Map<?,?>)finance.overview(a)).get("openItems")).stream().filter(row->r.granular(a,row.get("kind").equals("AR")?"receivables":"payables","EXPORT")).toList();case "report"->((List<Map<String,Object>>)((Map<?,?>)operations.report(a,from,to)).get("sales")).stream().filter(row->r.granular(a,Set.of("PURCHASE_RECEIPT","PURCHASE_RETURN").contains(row.get("type"))?"report-purchase":"report-sales","EXPORT")).toList();default->throw problem("EXPORT_KIND","Loại xuất không hợp lệ");});var csv=new StringBuilder("\ufeff");if(!rows.isEmpty()){var columns=new ArrayList<>(rows.getFirst().keySet());csv.append(String.join(",",columns)).append("\r\n");for(var row:rows){csv.append(columns.stream().map(c->escape(row.get(c))).collect(java.util.stream.Collectors.joining(","))).append("\r\n");}}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=aicrm-"+kind+".csv").contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).body(csv.toString());}
  private void exportPermission(Authentication a,String kind){String feature=switch(kind){case "suppliers"->"supplier";case "products"->"products";case "stock","movements"->"stock";case "payments"->"receipt";case "finance"->"receivables";case "report"->"report-sales";case "documents"->"";default->throw problem("EXPORT_KIND","Loại xuất không hợp lệ");};if(kind.equals("payments")){if(!r.granular(a,"receipt","EXPORT")&&!r.granular(a,"payment","EXPORT"))r.gate(a,"receipt","EXPORT");}else if(kind.equals("finance")){if(!r.granular(a,"receivables","EXPORT")&&!r.granular(a,"payables","EXPORT"))r.gate(a,"receivables","EXPORT");}else if(kind.equals("report")){if(!r.granular(a,"report-sales","EXPORT")&&!r.granular(a,"report-purchase","EXPORT"))r.gate(a,"report-sales","EXPORT");}else if(!feature.isEmpty())r.gate(a,feature,"EXPORT");}
  private List<Map<String,Object>> allDocuments(Authentication a){var rows=new ArrayList<Map<String,Object>>();int page=0;while(true){var result=(Map<?,?>)documents.list(a,"","","",page++);var items=(List<Map<String,Object>>)result.get("items");rows.addAll(items.stream().filter(d->r.granular(a,RetailPermissions.feature(d.get("type").toString()),"EXPORT")).toList());if(items.size()<50)break;}return rows;}
  private String escape(Object value){String text=value==null?"":value.toString();if(text.matches("^[=+@\\-].*"))text="'"+text;return "\""+text.replace("\"","\"\"")+"\"";}
}
